/** Thrown for any malformed line; the parser attaches the line number. */
export class Fail {
  constructor(reason) {
    this.reason = reason
  }
}

const NAME_CHAR = /[A-Za-z0-9_-]/
const INTEGER_RE = /^[+-]?[0-9]+(?:_[0-9]+)*$/
const FLOAT_RE = /^[+-]?[0-9]+(?:_[0-9]+)*(?:\.[0-9]+(?:_[0-9]+)*)?(?:[eE][+-]?[0-9]+(?:_[0-9]+)*)?$/

export class Scanner {
  constructor(line) {
    this.line = line
    this.idx = 0
  }

  skipWs() {
    while (this.idx < this.line.length && (this.line[this.idx] === ' ' || this.line[this.idx] === '\t')) {
      this.idx++
    }
  }

  /** True when nothing meaningful remains: end of line or a comment start. */
  finished() {
    this.skipWs()
    const c = this.line[this.idx]
    return this.idx >= this.line.length || c === '#' || c === ';'
  }

  /** The next meaningful character, or undefined at end/comment. */
  peek() {
    this.skipWs()
    if (this.finished()) return undefined
    return this.line[this.idx]
  }

  parseName() {
    this.skipWs()
    const c = this.line[this.idx]
    if (c === '"') return this.parseBasicString()
    if (c === "'") return this.parseLiteralString()
    const start = this.idx
    while (this.idx < this.line.length && NAME_CHAR.test(this.line[this.idx])) {
      this.idx++
    }
    if (this.idx === start) throw new Fail('expected a name')
    return this.line.slice(start, this.idx)
  }

  parseDottedName() {
    const segments = [this.parseName()]
    while (true) {
      this.skipWs()
      if (this.line[this.idx] === '.') {
        this.idx++
        segments.push(this.parseName())
      } else {
        break
      }
    }
    return segments
  }

  parseBasicString() {
    this.idx++ // consume opening quote
    let out = ''
    while (true) {
      if (this.idx >= this.line.length) throw new Fail('unterminated string')
      const c = this.line[this.idx]
      if (c === '"') {
        this.idx++
        return out
      }
      if (c === '\\') {
        this.idx++
        if (this.idx >= this.line.length) throw new Fail('unterminated string')
        const esc = this.line[this.idx]
        switch (esc) {
          case '"': out += '"'; this.idx++; break
          case '\\': out += '\\'; this.idx++; break
          case 'n': out += '\n'; this.idx++; break
          case 't': out += '\t'; this.idx++; break
          case 'r': out += '\r'; this.idx++; break
          case '0': out += '\0'; this.idx++; break
          case 'u': {
            const hex = this.line.slice(this.idx + 1, this.idx + 5)
            if (hex.length !== 4 || !/^[0-9A-Fa-f]{4}$/.test(hex)) {
              throw new Fail('invalid escape \\u')
            }
            out += String.fromCharCode(parseInt(hex, 16))
            this.idx += 5
            break
          }
          default:
            throw new Fail(`invalid escape \\${esc}`)
        }
      } else {
        out += c
        this.idx++
      }
    }
  }

  parseLiteralString() {
    this.idx++ // consume opening quote
    const start = this.idx
    while (true) {
      if (this.idx >= this.line.length) throw new Fail('unterminated string')
      if (this.line[this.idx] === "'") {
        const out = this.line.slice(start, this.idx)
        this.idx++
        return out
      }
      this.idx++
    }
