    this.idx++ // consume '['
    const items = []
    this.skipWs()
    if (!this.finished() && this.line[this.idx] === ']') {
      this.idx++
      return { kind: 'array', value: items }
    }
    while (true) {
      items.push(this.parseValue(path))
