      if (this.finished()) throw new Fail('unterminated array')
      const c = this.line[this.idx]
      if (c === ',') {
        this.idx++
        this.skipWs()
        if (!this.finished() && this.line[this.idx] === ']') {
          this.idx++
          return { kind: 'array', value: items }
        }
        continue
      }
      if (c === ']') {
        this.idx++
        return { kind: 'array', value: items }
      }
      throw new Fail('unterminated array')
    }
  }

  parseInlineTable(path) {
    this.idx++ // consume '{'
    const map = new Map()
    this.skipWs()
    if (!this.finished() && this.line[this.idx] === '}') {
      this.idx++
      return { kind: 'table', map, headerDefined: false }
    }
