      child = child.value[child.value.length - 1]
    } else {
      throw new Fail(`${pathSoFar} is not a table`)
    }
    node = child
  }
  const last = segs[segs.length - 1]
  if (node.map.has(last)) {
    throw new Fail(`key ${basePath.concat(segs).join('.')} is defined twice`)
  }
  node.map.set(last, value)
}
