 * Renders a parsed document tree (see parser.js) as canonical JSON or as a
 * flat `keys` listing.
 */

function compareCodePoints(a, b) {
  const ca = Array.from(a)
  const cb = Array.from(b)
  const len = Math.min(ca.length, cb.length)
  for (let i = 0; i < len; i++) {
    const pa = ca[i].codePointAt(0)
    const pb = cb[i].codePointAt(0)
    if (pa !== pb) return pa - pb
  }
  return ca.length - cb.length
}

function sortedKeys(map) {
  return Array.from(map.keys()).sort(compareCodePoints)
}

function jsonValue(node, indent) {
  const pad = '  '.repeat(indent)
  const padIn = '  '.repeat(indent + 1)
  switch (node.kind) {
    case 'table': {
      const keys = sortedKeys(node.map)
      if (keys.length === 0) return '{}'
      const parts = keys.map(
        (k) => `${padIn}${JSON.stringify(k)}: ${jsonValue(node.map.get(k), indent + 1)}`
      )
      return `{\n${parts.join(',\n')}\n${pad}}`
    }
    case 'array-of-tables':
    case 'array': {
      const items = node.value
      if (items.length === 0) return '[]'
      const parts = items.map((v) => `${padIn}${jsonValue(v, indent + 1)}`)
      return `[\n${parts.join(',\n')}\n${pad}]`
    }
    case 'string':
      return JSON.stringify(node.value)
    case 'integer':
    case 'float':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    default:
      throw new Error(`unknown node kind ${node.kind}`)
  }
}

export function toJson(root) {
  return `${jsonValue(root, 0)}\n`
}

function typeName(node) {
  switch (node.kind) {
    case 'table':
      return 'table'
    case 'array-of-tables':
    case 'array':
      return 'array'
    default:
      return node.kind
  }
}

function walkKeys(node, path, out) {
  out.push(`${path} ${typeName(node)}`)
  if (node.kind === 'table') {
    for (const k of sortedKeys(node.map)) {
      walkKeys(node.map.get(k), `${path}.${k}`, out)
    }
  } else if (node.kind === 'array-of-tables' || node.kind === 'array') {
    node.value.forEach((item, i) => walkKeys(item, `${path}[${i}]`, out))
  }
